"""Compute sellable units for a web shop item.

Rules:
- Each reservation holds its qty units while it is active.
- Paid reservations never expire. They always hold their units, so shelf
  stock is assumed not to be decremented on payment.
- Unpaid reservations expire HOLD_TTL_S seconds after creation. A reservation
  exactly HOLD_TTL_S seconds old has expired, because the boundary is exclusive.
- A reservation with created_s in the future (clock skew) is treated as active.
- The result is never less than 0.
"""

HOLD_TTL_S = 300


def _is_active(reservation, now_s, ttl_s):
    if reservation["paid"]:
        return True
    age = now_s - reservation["created_s"]
    return age < ttl_s  # negative age (future created_s) is active


def available(stock, reservations, now_s, ttl_s=HOLD_TTL_S):
    """Return how many units can still be sold.

    stock:        units on the shelf (non-negative int)
    reservations: iterable of dicts with keys qty, created_s, paid
    now_s:        current time in seconds, same clock as created_s
    ttl_s:        hold time for unpaid reservations (default 300)
    """
    if isinstance(stock, bool) or not isinstance(stock, int) or stock < 0:
        raise ValueError(f"stock must be a non-negative int, got {stock!r}")

    held = 0
    for i, r in enumerate(reservations):
        try:
            qty = r["qty"]
            r["created_s"]
            r["paid"]
        except (KeyError, TypeError) as exc:
            raise ValueError(f"reservation {i} is missing required keys: {r!r}") from exc
        if isinstance(qty, bool) or not isinstance(qty, int) or qty < 0:
            raise ValueError(f"reservation {i} has invalid qty: {qty!r}")
        if _is_active(r, now_s, ttl_s):
            held += qty

    return max(0, stock - held)


if __name__ == "__main__":
    import unittest

    class AvailableTests(unittest.TestCase):
        def test_empty(self):
            self.assertEqual(available(10, [], 1000), 10)

        def test_zero_stock(self):
            self.assertEqual(available(0, [], 1000), 0)

        def test_unpaid_active(self):
            r = [{"qty": 3, "created_s": 900, "paid": False}]
            self.assertEqual(available(10, r, 1000), 7)

        def test_unpaid_just_before_expiry(self):
            r = [{"qty": 3, "created_s": 0, "paid": False}]
            self.assertEqual(available(10, r, 299), 7)

        def test_unpaid_expires_at_ttl(self):
            r = [{"qty": 3, "created_s": 0, "paid": False}]
            self.assertEqual(available(10, r, 300), 10)

        def test_paid_never_expires(self):
            r = [{"qty": 4, "created_s": 0, "paid": True}]
            self.assertEqual(available(10, r, 10**9), 6)

        def test_mixed(self):
            r = [
                {"qty": 2, "created_s": 0, "paid": True},
                {"qty": 3, "created_s": 0, "paid": False},    # expired
                {"qty": 1, "created_s": 950, "paid": False},  # active
            ]
            self.assertEqual(available(10, r, 1000), 7)

        def test_oversell_clamped(self):
            r = [{"qty": 15, "created_s": 0, "paid": True}]
            self.assertEqual(available(10, r, 1), 0)

        def test_future_created_is_active(self):
            r = [{"qty": 2, "created_s": 2000, "paid": False}]
            self.assertEqual(available(10, r, 1000), 8)

        def test_missing_key(self):
            with self.assertRaises(ValueError):
                available(10, [{"qty": 1, "paid": False}], 0)

        def test_negative_stock(self):
            with self.assertRaises(ValueError):
                available(-1, [], 0)

    unittest.main()
